UPDATE ast06_tr
   SET ast06_amt            = #{r.amt},
       ast06_fee            = #{r.fee},
       ast06_settle_mng_yn  = #{r.settleMngYn},
       ast06_note           = #{r.note},
       ast06_deposit_id     = #{r.depositId},
       ast06_for_amt        = #{r.amt}
 WHERE ast06_tr_id      = #{r.trId}
   AND ast06_company_id = #{companyId}
